import { useState } from "react";
import { useEffect } from "react";
import jsondata from "../json/modal_verb_level1.json";
import { Button, FormControl, MenuItem, Select, Slider } from "@mui/material";
import { useNavigate } from "react-router-dom";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";
import "../style/level1.css";

const Level1 = () => {
  // Load Json to mainArr variable ....
  var [mainArr, setmainArr] = useState(jsondata);
  var no;
  var nextno;
  var status;
  var arrlen;
  var [arrlen, setArrlen] = useState(Object.keys(mainArr).length - 1);
  var [currentsentence, setCurrentsentence] = useState("");
  var [currentmodal, setCurrentmodal] = useState("");
  var [currentmodalfeedback, setCurrentmodalfeedback] = useState("");
  var [currentmodalop, setCurrentmodalop] = useState([]);
  var [disable, setDisable] = useState(false);
  var [splitsentence, setSplitsentence] = useState([]);
  let [visitedno, setVisitedno] = useState([]);
  var [flag, SetFlag] = useState(false);
  var [flag1, SetFlag1] = useState(true);
  var [flag2, SetFlag2] = useState(false);
  var [flag3, SetFlag3] = useState(false);
  var [flag4, SetFlag4] = useState(false);
  var [flag5, SetFlag5] = useState(0);
  const [progress, setProgress] = useState(0);
  var [score, setScore] = useState(0);
  var [selectedword, setSelectedword] = useState();
  const navigate = useNavigate();
  const { t, i18n } = useTranslation();
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 1 page");
  let [level, setLevel] = useState("Level 1");

  useEffect(() => {
    outerfunction();
  }, []);

  useEffect(() => {
    splitsentence =
      typeof currentsentence === "string" ? currentsentence.split(" ") : [];
    setSplitsentence(splitsentence);
  }, [currentsentence]);

  const outerfunction = () => {
    no = randomNumberInRange(0, arrlen);
    console.log(mainArr[no]["sentence"]);
    setCurrentsentence(mainArr[no]["sentence"]);
    setCurrentmodal(mainArr[no]["verb"]["modalverb"]);
    setCurrentmodalfeedback(mainArr[no]["verb"]["modalverb_feedback"]);
    setCurrentmodalop(mainArr[no]["verb"]["modalverb_option"]);
    visitedno = [...visitedno, no];
    setVisitedno(visitedno);
  };

  function randomNumberInRange(min, max) {
    // get number between min (inclusive) and max (inclusive)
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  const selchange = (e) => {
    setSelectedword(e.target.value);
    if (currentmodal == e.target.value) {
      document.getElementById("modaloption").style.backgroundColor = "#098B0D";
      document.getElementById("modaloption").style.color = "white";
      setDisable(true);
      SetFlag1(false);
      var enterval = e.target.value;
      SetFlag3(true);
      ReactGA.event({
        action:
          "English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on dropdown button for correct verb",
        category:
          "English CDAC-OlabsNxtG-En-8 | level-1 dropdown button for correct verb selected",
        label:
          "English CDAC-OlabsNxtG-En-8 | level-1 dropdown button for correct verb selected",
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        "dropdown button",
        "Clicked",
        "checked selected dropdown option is right or wrong",
        [{ input: { enterval }, answer: { currentmodal }, result: "correct" }]
      );
      flag5 = 1;
      SetFlag5(flag5);
    } else {
      document.getElementById("modaloption").style.backgroundColor = "#BF4C4C";
      document.getElementById("modaloption").style.color = "white";
      var enterval = e.target.value;
      ReactGA.event({
        action:
          "English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on dropdown button for incorrect verb",
        category:
          "English CDAC-OlabsNxtG-En-8 | level-1 dropdown button for incorrect verb selected",
        label:
          "English CDAC-OlabsNxtG-En-8 | level-1 dropdown button for incorrect verb selected",
      });
      SendLogData(
        sendJsonMessage,
        pageName,
        "dropdown button",
        "Clicked",
        "checked selected dropdown option is right or wrong",
        [{ input: { enterval }, answer: { currentmodal }, result: "incorrect" }]
      );
      flag5 = 2;
      SetFlag5(flag5);
    }
  };

  const nextbtn = () => {
    score = score + 1;
    setScore(score);
    do {
      nextno = randomNumberInRange(0, arrlen);
      setCurrentsentence(mainArr[nextno]["sentence"]);
      setCurrentmodal(mainArr[nextno]["verb"]["modalverb"]);
      setCurrentmodalfeedback(mainArr[nextno]["verb"]["modalverb_feedback"]);
      setCurrentmodalop(mainArr[nextno]["verb"]["modalverb_option"]);
      if (visitedno.length === arrlen + 1) {
        SetFlag(true);
        SetFlag4(true);
      } else {
        if (visitedno.includes(nextno)) {
          status = true;
        } else {
          status = false;
          setDisable(false);
          SetFlag1(true);
          SetFlag3(false);
          visitedno = [...visitedno, nextno];
          setVisitedno(visitedno);
          SetFlag5(0)
          ReactGA.event({
            action:
              "English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on Next button",
            category:
              "English CDAC-OlabsNxtG-En-8 | level-1 Next button clicked",
            label:
              "English CDAC-OlabsNxtG-En-8 | level-1 Next button clicked for next sentence",
          });
          SendLogData(
            sendJsonMessage,
            pageName,
            'Level-1 "Next" button',
            "Clicked",
            'Level-1 "Next" button for next sentence'
          );
        }
      }
    } while (status);
    setProgress(progress + 1);
  };

  const handleskipbtn = () => {
    do {
      nextno = randomNumberInRange(0, arrlen);
      setCurrentsentence(mainArr[nextno]["sentence"]);
      setCurrentmodal(mainArr[nextno]["verb"]["modalverb"]);
      setCurrentmodalfeedback(mainArr[nextno]["verb"]["modalverb_feedback"]);
      setCurrentmodalop(mainArr[nextno]["verb"]["modalverb_option"]);
      if (visitedno.length === arrlen + 1) {
        SetFlag(true);
        SetFlag4(true);
      } else {
        if (visitedno.includes(nextno)) {
          status = true;
        } else {
          status = false;
          setDisable(false);
          SetFlag1(true);
          visitedno = [...visitedno, nextno];
          setVisitedno(visitedno);
          SetFlag5(0)
          ReactGA.event({
            action:
              "English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on Skip button",
            category:
              "English CDAC-OlabsNxtG-En-8 | level-1 Skip button clicked",
            label:
              "English CDAC-OlabsNxtG-En-8 | level-1 Skip button clicked for next sentence",
          });
          SendLogData(
            sendJsonMessage,
            pageName,
            'Level-1 "Skip" button',
            "Clicked",
            'Level-1 "Skip" button for next sentence'
          );
        }
      }
    } while (status);
    setProgress(progress + 1);
  };


  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-8 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-8 | "Restart" button clicked and level 1 restarted',
    });
    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and level 1 restarted'
    );
    window.location.reload();
  };

  const handleLevelChange = (event) => {
    switch (event.target.value) {
      case "Level 1":
        navigate("/launchpage/englishactivity/level1");
        break;
      case "Level 2":
        ReactGA.event({
          action:
            'English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on "Level 2" button from dropdown',
          category:
            'English CDAC-OlabsNxtG-En-8 | "Level 2" button from dropdown clicked',
          label:
            'English CDAC-OlabsNxtG-En-8 | "Level 2" button form dropdown clicked and level 2 started',
        });

        SendLogData(
          sendJsonMessage,
          pageName,
          '"Level 2" button from dropdown',
          "Clicked",
          '"Level 2" button from dropdown clicked and level 2 started'
        );
        navigate("/launchpage/englishactivity/level2");
        break;
      default:
        console.log("Bad choice!");
        break;
    }
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag == true ? (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center" style={{ fontSize: "calc(1rem + .4vw)" }}>
                <b>{t("level_1_title")}</b>
              </div>
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">{t("level_1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level_2")}</MenuItem>
                </Select>
              </FormControl>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-6 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  backgroundColor: "#EDF6FA",
                  fontSize: "calc(.6rem + .4vw)"
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have scored {score} out of {arrlen + 1} sentences.
                </p>
                <div>
                  <Button variant="contained" onClick={restartbtn} style={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}>
                    {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center" style={{ fontSize: "calc(1rem + .4vw)" }}>
                <b>{t("level_1_title")}</b>
              </div>
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <Select
                  labelId="demo-simple-select-label"
                  id="demo-simple-select"
                  value={level}
                  onChange={handleLevelChange}
                  sx={{
                    bgcolor: "green",
                    borderRadius: 1,
                    "& .MuiOutlinedInput-notchedOutline": {
                      borderColor: "green",
                    },
                    color: "white",
                  }}
                >
                  <MenuItem value="Level 1">{t("level_1")}</MenuItem>
                  <MenuItem value="Level 2">{t("level_2")}</MenuItem>
                </Select>
              </FormControl>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "5vh", fontSize: "calc(.6rem + .4vw)" }}
            >
              <span className="me-3">Sentence</span>

              <Slider
                defaultValue={1}
                step={1}
                min={1}
                max={arrlen + 1}
                value={progress + 1}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />

              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  fontSize: "calc(.6rem + .4vw)"
                }}
              >
                {progress + 1}/{arrlen + 1}
              </span>
            </div>

            <div
              className="d-flex justify-content-center align-items-center "
              style={{
                overflow: "auto",
                backgroundColor: "#D6EAF8",
                borderRadius: "13px",
                boxShadow: "0px 3px 6px #00000029",
                display: "block",
                marginLeft: "auto",
                marginRight: "auto",
                marginTop: "5%",
                cursor: "pointer",
                padding: "2%",
                backgroundColor: "#EDF6FA"
              }}
            >
              <div
                className="row-md-auto "
                style={{ overflow: "auto", fontWeight: "bolder", fontSize: "calc(.6rem + .4vw)" }}
              >
                <div className="row-md-auto d-flex">
                  {splitsentence.map((slot, idx) => (
                    <>
                      {currentmodal == slot ? (
                        <>
                          <select
                            name="options"
                            id="modaloption"
                            onChange={selchange}
                            disabled={disable}
                            style={{
                              boxShadow: "0px 3px 6px #00000029",
                              background: "#F5B946 0% 0% no-repeat padding-box",
                              borderRadius: "2px",
                              color: "black",
                              textAlign: "center",
                              fontweight: "bolder",
                            }}
                          >
                            <option value="">select</option>
                            {currentmodalop.map((item, idx1) => (
                              <option value={item} className="">
                                {item}
                              </option>
                            ))}
                          </select>
                          &nbsp;&nbsp;
                        </>
                      ) : (
                        <>
                          <div className="">{slot}</div>&nbsp;&nbsp;
                        </>
                      )}
                    </>
                  ))}
                </div>
              </div>
            </div>

            <div
              className="row-md-auto d-flex justify-content-around"
              style={{ marginTop: "5vh" }}
            >
              <Button
                variant="contained"
                onClick={handleskipbtn}
                disabled={flag3}
                sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}
              >
                {t("skip")}
              </Button>
              <Button variant="contained" onClick={nextbtn} disabled={flag1} sx={{ backgroundColor: "#0F477E", fontSize: "calc(.6rem + .4vw)" }}>
                {t("next")}
              </Button>
            </div>

            <div className="row justify-content-center mt-4 text-center" style={{ fontSize: "calc(.6rem + .4vw)" }}>
              {flag5 == 1 ? (
                <div className="feedback">
                  <span >Correct.
                    <span className="green-text"> <b>{selectedword}</b> </span> is the correct modal verb.</span>
                </div>
              ) : flag5 == 2 ? (
                <div className="feedback">
                  <span >Incorrect.
                    <span className="red-text">
                      {" "}
                      <b>{selectedword}</b> </span> is an incorrect verb.<br></br>
                    <b>Hint</b>: {currentmodalfeedback}
                  </span>
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", fontSize: "calc(.6rem + .4vw)" }}>
            <div className="">
              {flag4 == true ? (
                <ul>
                  <li>{t("instruction_1_8")}</li>
                </ul>
              ) : flag1 == true ? (
                <ul>
                  <li>{t("instruction_1_1")}</li>
                  <li>{t("instruction_1_2")}</li>
                  <li>{t("instruction_1_3")}</li>{" "}
                  <li>{t("instruction_1_4")}</li>
                  <li>{t("instruction_1_5")}</li>
                  <li><u>{t("note")}</u>:- {t("instruction_1_7")}</li>
                </ul>
              ) : (
                <ul>
                  <li>{t("instruction_1_6")}</li>
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* <InfoPopUpForDetailView
      openDialog={showDialogue}
      onAgree={onAgree}
      content={<ViewDetailsPopup sentence={sentence} />}
      popuptitle="Hint"
    /> */}
    </div>
  );
};

export default Level1;
