import { useState } from "react";
import { Button } from "@mui/material";
import Level1 from "../Images/Level1.png";
import Level2 from "../Images/Level2.png";
import { useNavigate } from "react-router-dom";
import { Card } from "react-bootstrap";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";
import { useTranslation } from "react-i18next";
import "animate.css";

const Selectlevel = () => {
  // Load Json to mainArr variable ....
  const navigate = useNavigate();
  const { t, i18n } = useTranslation();

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level start page");

  const tolevel1 = () => {
    ReactGA.event({
      action:
        'English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on level 1 "Lets Go" button',
      category:
        'English CDAC-OlabsNxtG-En-8 | level 1 "Lets Go" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-8 | "Lets Go" button clicked and level 1 started',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level 1 "Lets Go" button',
      "Clicked",
      'Level 1 "Lets Go" button clicked and level 1 started'
    );
    navigate("/launchpage/englishactivity/level1");
  };

  const tolevel2 = () => {
    ReactGA.event({
      action:
        'English Modal verb | CDAC-OlabsNxtG-En-8 | Clicked on level 2 "Lets Go" button',
      category:
        'English CDAC-OlabsNxtG-En-8 | level 2 "Lets Go" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-8 | "Lets Go" button clicked and level 2 started',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level 2 "Lets Go" button',
      "Clicked",
      'Level 2 "Lets Go" button clicked and level 2 started'
    );
    navigate("/launchpage/englishactivity/level2");
  };

  return (
    <div>
      <div
        className="row scrollbar-primary"
        style={{
          height: "100%",
          width: "93vw",
          overflowX: "hidden",
          overflowY: "auto",
        }}
      >
        <div className="col d-flex justify-content-center align-items-center mb-3 mt-3 animate__animated animate__bounceInLeft">
          <Card style={{ width: "18rem" }}>
            <Card.Img variant="top" src={Level1} />
            <Card.Body className="text-center">
              <Card.Title style={{fontSize: "calc(.6rem + .6vw)"}}>{t("level_1_title")}</Card.Title>
              <Button variant="contained" onClick={tolevel1} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                {t("lets_go")}
              </Button>
            </Card.Body>
          </Card>
        </div>
        <div className="col d-flex justify-content-center align-items-center mb-3 mt-3 animate__animated animate__bounceInRight">
          <Card style={{ width: "18rem" }}>
            <Card.Img variant="top" src={Level2} />
            <Card.Body className="text-center">
              <Card.Title style={{fontSize: "calc(.6rem + .6vw)"}}>{t("level_2_title")}</Card.Title>
              <Button variant="contained" onClick={tolevel2} style={{fontSize: "calc(.6rem + .4vw)", backgroundColor: "#0F477E"}}>
                {t("lets_go")}
              </Button>
            </Card.Body>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default Selectlevel;
